<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,Pembayaran,Servis,Sparepart,Transaksi,User}; use App\Services\{BookingServisService,PaymentService,ServisService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use Illuminate\Support\Facades\Schema; use Illuminate\Http\UploadedFile; use RuntimeException; use Tests\TestCase;
class ServicePaymentStage5DTest extends TestCase { use DatabaseTransactions;
 private function user(string $r):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$r))->firstOrFail();}
 private function transaction(string $total='100000.00'):Transaksi{$u=$this->user('pelanggan');$v=$u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Payment','nomor_polisi'=>'PY-'.random_int(1000,9999),'kilometer'=>50000,'status'=>'aktif']);$t=JenisServis::where('status','aktif')->firstOrFail();$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'14:00',null,null);$b->forceFill(['status'=>'diterima'])->save();$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);app(ServisService::class)->updateInspection($s->id_servis,'Diagnosis',null);$tx=new Transaksi();$tx->forceFill(['kode_transaksi'=>'TRX-QA-'.random_int(100000,999999),'id_pelanggan'=>$s->id_pelanggan,'id_petugas'=>$s->id_petugas,'jenis_transaksi'=>'servis','tanggal'=>now(),'subtotal'=>$total,'diskon'=>0,'total'=>$total,'status'=>'belum_bayar','catatan'=>'QA'])->save();$s->forceFill(['id_transaksi'=>$tx->id_transaksi])->save();return $tx->fresh();}
 public function test_baseline_payment_import_is_present_and_does_not_recalculate():void{$this->assertSame(11,Pembayaran::count());$this->assertDatabaseHas('pembayaran',['id_pembayaran'=>5,'id_transaksi'=>4,'metode'=>'tunai','status'=>'terverifikasi']);$this->assertSame('lunas',Transaksi::find(4)->status);}
 public function test_cash_is_created_verified_and_marks_service_complete():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,$this->user('petugas')->petugas->id_petugas,'100000','tunai',null,'cash');$this->assertSame('terverifikasi',$p->status);$this->assertSame('lunas',$tx->fresh()->status);$this->assertSame('selesai',$tx->servis->fresh()->status);$this->assertSame('selesai',$tx->servis->bookingServis->fresh()->status);}
 public function test_transfer_is_pending_and_not_counted():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,$this->user('petugas')->petugas->id_petugas,'60000','transfer','proof.pdf',null);$this->assertSame('menunggu',$p->status);$this->assertSame('belum_bayar',$tx->fresh()->status);$this->assertSame('0.00',app(PaymentService::class)->summary($tx->id_transaksi)['paid']);}
 public function test_verify_transfer_moves_transaction_to_dp():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,2,'60000','transfer',null,null);app(PaymentService::class)->verify($p->id_pembayaran,2);$this->assertSame('dp',$tx->fresh()->status);$this->assertSame('60000.00',app(PaymentService::class)->summary($tx->id_transaksi)['paid']);$this->assertSame('dikerjakan',$tx->servis->fresh()->status);}
 public function test_reject_keeps_history_and_not_paid():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,2,'60000','transfer',null,null);app(PaymentService::class)->reject($p->id_pembayaran,2);$this->assertSame('ditolak',$p->fresh()->status);$this->assertSame('0.00',app(PaymentService::class)->summary($tx->id_transaksi)['paid']);}
 public function test_zero_negative_and_overpayment_are_rejected():void{$tx=$this->transaction();$svc=app(PaymentService::class);foreach(['0','-1','100001'] as $amount){try{$svc->create($tx->id_transaksi,2,$amount,'tunai',null,null);$this->fail('Invalid payment accepted');}catch(RuntimeException $e){$this->assertTrue(true);}}$this->assertSame(0,Pembayaran::where('id_transaksi',$tx->id_transaksi)->count());}
 public function test_multiple_verified_payments_reach_dp_then_lunas():void{$tx=$this->transaction();$svc=app(PaymentService::class);$svc->create($tx->id_transaksi,2,'30000','tunai',null,null);$this->assertSame('dp',$tx->fresh()->status);$svc->create($tx->id_transaksi,2,'70000','tunai',null,null);$this->assertSame('lunas',$tx->fresh()->status);}
 public function test_client_cannot_forge_status_or_total():void{$tx=$this->transaction();$this->actingAs($this->user('petugas'))->post('/petugas/transaksi-servis/'.$tx->id_transaksi.'/pembayaran',['jumlah'=>'10000','metode'=>'tunai','status'=>'lunas','total'=>'999999'])->assertRedirect();$this->assertSame('dp',$tx->fresh()->status);$this->assertSame('100000.00',$tx->fresh()->total);}
 public function test_double_verify_and_reject_replay_are_blocked():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,2,'10000','transfer',null,null);app(PaymentService::class)->verify($p->id_pembayaran,2);$this->expectException(RuntimeException::class);app(PaymentService::class)->verify($p->id_pembayaran,2);}
 public function test_payment_after_lunas_is_overpayment_protected():void{$tx=$this->transaction();$svc=app(PaymentService::class);$svc->create($tx->id_transaksi,2,'100000','tunai',null,null);$this->expectException(RuntimeException::class);$svc->create($tx->id_transaksi,2,'1','tunai',null,null);}
 public function test_rejected_payment_does_not_complete_service():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,2,'100000','transfer',null,null);app(PaymentService::class)->reject($p->id_pembayaran,2);$this->assertSame('belum_bayar',$tx->fresh()->status);$this->assertSame('dikerjakan',$tx->servis->fresh()->status);}
 public function test_customer_cannot_mutate_payment_or_view_other_invoice():void{$tx=$this->transaction();$owner=$tx->pelanggan->user;$this->actingAs($owner)->post('/pelanggan/transaksi-servis/'.$tx->id_transaksi.'/pembayaran',['jumlah'=>1,'metode'=>'tunai'])->assertNotFound();$other=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->where('id_user','<>',$owner->id_user)->first();if($other)$this->actingAs($other)->get('/pelanggan/invoice/servis/'.$tx->id_transaksi)->assertForbidden();}
 public function test_invoice_contains_service_items_and_payment_history():void{$tx=$this->transaction();app(PaymentService::class)->create($tx->id_transaksi,2,'10000','tunai',null,'one');$this->actingAs($this->user('admin'))->get('/admin/invoice/servis/'.$tx->id_transaksi)->assertOk()->assertSee($tx->kode_transaksi)->assertSee('one');}
 public function test_admin_and_petugas_can_access_invoice_and_payment_actions():void{$tx=$this->transaction();$this->actingAs($this->user('admin'))->get('/admin/invoice/servis/'.$tx->id_transaksi)->assertOk();$this->actingAs($this->user('petugas'))->get('/petugas/transaksi-servis/'.$tx->id_transaksi.'/pembayaran/create')->assertOk();}
 public function test_stock_is_unchanged_by_payment():void{$tx=$this->transaction();$stock=(int)Sparepart::find(1)->stok;app(PaymentService::class)->create($tx->id_transaksi,2,'100000','tunai',null,null);$this->assertSame($stock,(int)Sparepart::find(1)->fresh()->stok);}
 public function test_payment_and_transaction_are_atomic():void{$tx=$this->transaction();$before=Transaksi::find($tx->id_transaksi)->status;$this->expectException(RuntimeException::class);try{app(PaymentService::class)->verify(999999,2);}finally{$this->assertSame($before,Transaksi::find($tx->id_transaksi)->status);}}
 public function test_payment_schema_and_no_gateway_tables():void{$this->assertTrue(Schema::hasTable('pembayaran'));$this->assertFalse(Schema::hasTable('midtrans_orders'));}
 public function test_invoice_is_customer_scoped():void{$tx=$this->transaction();$this->actingAs($this->user('pelanggan'))->get('/pelanggan/invoice/servis/'.$tx->id_transaksi)->assertOk();}
 public function test_transfer_upload_uses_validation_and_remains_pending():void{$tx=$this->transaction();$this->actingAs($this->user('petugas'))->post('/petugas/transaksi-servis/'.$tx->id_transaksi.'/pembayaran',['jumlah'=>'10000','metode'=>'transfer','bukti_transfer'=>UploadedFile::fake()->create('proof.pdf',100,'application/pdf')])->assertRedirect();$this->assertSame('menunggu',Pembayaran::where('id_transaksi',$tx->id_transaksi)->latest('id_pembayaran')->value('status'));}
 public function test_non_service_transaction_payment_is_rejected():void{$tx=Transaksi::where('jenis_transaksi','<>','servis')->firstOrFail();$this->expectException(RuntimeException::class);app(PaymentService::class)->create($tx->id_transaksi,2,'1','tunai',null,null);}
 public function test_rejected_payment_cannot_be_verified_again():void{$tx=$this->transaction();$p=app(PaymentService::class)->create($tx->id_transaksi,2,'10000','transfer',null,null);app(PaymentService::class)->reject($p->id_pembayaran,2);$this->expectException(RuntimeException::class);app(PaymentService::class)->verify($p->id_pembayaran,2);}
}
